namespace Fanex.Age.UI.Forecast
{
    public partial class FCAH_Page : Fanex.Age.UI.TplPage
    {
        #region Const
        private const int NEXT_GOAL_BET_TYPE = 22;
        #endregion

        #region Variable
        private int _currentScore = 0;
        private int _betType = 0;
        private int _matchId = 0;
        private bool _fullMode = true;
        ForecastBO _forecastBO = null;
        #endregion

        #region Override
        /// <summary>
        /// 
        /// </summary>
        /// <param name="writer"></param>
        public override void RenderContent(HtmlTextWriter writer)
        {
            RenderFCAH(writer);
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
            p.AddHttpParameters(new string[] { 
                "matchid", 
                "b" ,
                "score"
            }, Request);
            _currentScore = p["score"] == null ? 0 : Convert.ToInt32(p["score"]);
            _fullMode = String.IsNullOrEmpty(Request["full_mode"]) ? true : Convert.ToInt32(Request["full_mode"]) > 0;
            _matchId = Convert.ToInt32(p["matchid"]);
            _betType = Convert.ToInt32(p["b"]);
            if (_betType == 0) _betType = 1;
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            _forecastBO = new ForecastBO(CurrentUserSession.NetSessionId);
            Hashtable viewData = new Hashtable();
            DataTable oddsData = _forecastBO.GetFCTopOddsByMatch(_matchId, _betType);

            decimal FCValue0 = 0, FCValue1 = 0, FCValue2 = 0, FCValue3 = 0, FCValue4 = 0;
            bool hasData = false;
            // Forecast value
            if (_betType == 1 || _betType == 7)
            {
                hasData = GetFCHD(ref FCValue0, ref FCValue1, ref FCValue2, ref FCValue3, ref FCValue4);
            }
            else
            {
                hasData = GetFCOU(ref FCValue0, ref FCValue1, ref FCValue2, ref FCValue3, ref FCValue4);
            }

            viewData.Add("OddsData", oddsData);
            viewData.Add("FCValue0", FCValue0);
            viewData.Add("FCValue1", FCValue1);
            viewData.Add("FCValue2", FCValue2);
            viewData.Add("FCValue3", FCValue3);
            viewData.Add("FCValue4", FCValue4);
            viewData.Add("HasData", hasData);

            return viewData;
        }
        #endregion

        #region Render FCAH

        #region Calculation
        /// <summary>
        /// Calculate HD forecast value
        /// </summary>
        /// <param name="dr"></param>
        /// <param name="currentScore"></param>
        /// <param name="scoreOffset"></param>
        /// <param name="forecast"></param>
        /// <returns></returns>
        private decimal GetFCHDValue(DataRow dr, int currentScore, int scoreOffset, decimal forecast)
        {
            decimal forecastScore = currentScore - ((decimal)dr["offset"]) + scoreOffset;
            if (forecastScore > 0 && forecastScore < (decimal)(0.5))
            {
                forecast += ((decimal)dr["al"]) / 2; // win 1/2
            }
            else if (forecastScore >= (decimal)(0.5))
            {
                forecast += ((decimal)dr["al"]);
            }
            else if (forecastScore < 0 && forecastScore > -(decimal)(0.5))
            {
                forecast += ((decimal)dr["hl"]) / 2;
            }
            else if (forecastScore <= (decimal)(-0.5))
            {
                forecast += ((decimal)dr["hl"]);
            }
            return forecast;
        }
        /// <summary>
        /// Calculate OU forecast value
        /// </summary>
        /// <param name="dr"></param>
        /// <param name="currentScore"></param>
        /// <param name="scoreOffset"></param>
        /// <param name="forecast"></param>
        /// <returns></returns>
        private decimal GetFCOUValue(DataRow dr, int currentScore, int scoreOffset, decimal forecast)
        {
            decimal forecastScore = currentScore - ((decimal)dr["offset"]) + scoreOffset;
            if (forecastScore == (decimal)(0.25))
            {
                forecast += ((decimal)dr["al"]) / 2;
            }
            else if (forecastScore > (decimal)(0.25))
            {
                forecast += ((decimal)dr["al"]);
            }
            else if (forecastScore == (decimal)(-0.25))
            {
                forecast += ((decimal)dr["hl"]) / 2;
            }
            else if (forecastScore < (decimal)(-0.25))
            {
                forecast += ((decimal)dr["hl"]);
            }
            return forecast;
        }
        /// <summary>
        /// Calculate 5 HD forecast value
        /// </summary>
        /// <param name="FCValue0"></param>
        /// <param name="FCValue1"></param>
        /// <param name="FCValue2"></param>
        /// <param name="FCValue3"></param>
        /// <param name="FCValue4"></param>
        /// <returns>Return false if there is no data</returns>
        private bool GetFCHD(ref decimal FCValue0, ref decimal FCValue1, ref decimal FCValue2, ref decimal FCValue3, ref decimal FCValue4)
        {
            DataTable dtData = _forecastBO.GetFCHD(_matchId, _betType);
            foreach (DataRow dr in dtData.Rows)
            {
                FCValue0 = GetFCHDValue(dr, _currentScore, -2, FCValue0);
                FCValue1 = GetFCHDValue(dr, _currentScore, -1, FCValue1);
                FCValue2 = GetFCHDValue(dr, _currentScore, 0, FCValue2);
                FCValue3 = GetFCHDValue(dr, _currentScore, 1, FCValue3);
                FCValue4 = GetFCHDValue(dr, _currentScore, 2, FCValue4);
            }
            return dtData.Rows.Count > 0 ? true : false;
        }
        /// <summary>
        /// Calculate 5 OU forecast value
        /// </summary>
        /// <param name="FCValue0"></param>
        /// <param name="FCValue1"></param>
        /// <param name="FCValue2"></param>
        /// <param name="FCValue3"></param>
        /// <param name="FCValue4"></param>
        /// <returns>Return false if there is no data</returns>
        private bool GetFCOU(ref decimal FCValue0, ref decimal FCValue1, ref decimal FCValue2, ref decimal FCValue3, ref decimal FCValue4)
        {
            DataTable dtData = _forecastBO.GetFCOU(_matchId, _betType);
            foreach (DataRow dr in dtData.Rows)
            {
                FCValue0 = GetFCOUValue(dr, _currentScore, 0, FCValue0);
                FCValue1 = GetFCOUValue(dr, _currentScore, 1, FCValue1);
                FCValue2 = GetFCOUValue(dr, _currentScore, 2, FCValue2);
                FCValue3 = GetFCOUValue(dr, _currentScore, 3, FCValue3);
                FCValue4 = GetFCOUValue(dr, _currentScore, 4, FCValue4);
            }
            return dtData.Rows.Count > 0 ? true : false;
        }

        #endregion

        #region Render Utility
        /// <summary>
        /// Render FCAH
        /// </summary>
        /// <param name="writer"></param>
        private void RenderFCAH(HtmlTextWriter writer)
        {
            FCAH_Template tpl = new FCAH_Template();
            Hashtable viewData = View as Hashtable;

            DataTable topodds = viewData["OddsData"] as DataTable;

            if (topodds.Rows.Count > 0)
            {
                DataRow dr = topodds.Rows[0];
                int liveHomeScore = Convert.ToInt16(dr["livehomescore"]);
                int liveAwayScore = Convert.ToInt16(dr["liveawayscore"]);
                string home = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(dr["homeid"]) + ((bool)dr["isNeutral"] ? Resources.Lang.IsNeutral : String.Empty);
                string away = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(dr["awayid"]);

                FCAH_Content_ForecastContent_Block forecastContent = tpl.Content.ForecastContent;
                forecastContent.Home = home;
                forecastContent.Away = away;
                forecastContent.LiveAwayScore = liveAwayScore.ToString();
                forecastContent.LiveHomeScore = liveHomeScore.ToString();
                forecastContent.BetType = _betType.ToString();
                forecastContent.ScoreValue = _currentScore.ToString();


                // Title and switch link
                RenderForecastTitle(tpl.Content.ForecastContent);
                // Forecast index link
                RenderForecastIndexLink(tpl.Content.ForecastContent);
                // Forecast value
                RenderForecastValue(viewData, tpl.Content.ForecastContent.ForecastValue, tpl.Content.ForecastContent.NoInfo);
                // Toggle link
                RenderToogleLink(tpl.Content.ForecastContent);
                // BetList link
                RenderBetListLink(viewData, tpl.Content.ForecastContent.BetListLink);

                tpl.Content.NoInfo.Hide();
            }
            else
            {
                tpl.Content.ForecastContent.Hide();
            }

            // For FPS.
            RenderFPSArea(tpl);

            if (_fullMode) writer.Write(tpl);
            else writer.Write(tpl.Content);
        }

        /// <summary>
        /// Render the title
        /// </summary>
        /// <param name="content"></param>
        private void RenderForecastTitle(FCAH_Content_ForecastContent_Block forecastContent)
        {
            switch (_betType)
            {
                case 1:
                    forecastContent.Title = Resources.Lang.lblHandicapFC;
                    break;
                case 3:
                    forecastContent.Title = Resources.Lang.lblOverUnder;
                    break;
                case 7:
                    forecastContent.Title = Resources.Lang.lbl1stHdp;
                    break;
                case 8:
                    forecastContent.Title = Resources.Lang.lbl1stOU;
                    break;
                default: break;
            }
        }
        /// <summary>
        /// Render empty forcast in case there is no available data
        /// </summary>
        /// <param name="viewData"></param>
        /// <param name="forecastContent"></param>
        /// <param name="noInfoBlock"></param>
        private void RenderForecastValue(Hashtable viewData, FCAH_Content_ForecastContent_ForecastValue_Block forecastContent, FCAH_Content_ForecastContent_NoInfo_Block noInfoBlock)
        {
            if ((bool)viewData["HasData"])
            {
                forecastContent.FCValue0 = RedForPositiveAmount(viewData["FCValue0"], 2);
                forecastContent.FCValue1 = RedForPositiveAmount(viewData["FCValue1"], 2);
                forecastContent.FCValue2 = RedForPositiveAmount(viewData["FCValue2"], 2);
                forecastContent.FCValue3 = RedForPositiveAmount(viewData["FCValue3"], 2);
                forecastContent.FCValue4 = RedForPositiveAmount(viewData["FCValue4"], 2);
                // Forecast index
                RenderForecastIndex(forecastContent);

                noInfoBlock.Hide();
            }
            else
            {
                forecastContent.Hide();
            }

        }
        /// <summary>
        /// Render toogle link: view handicap forecast, view over under forecast
        /// </summary>
        /// <param name="forecastContent"></param>
        private void RenderToogleLink(FCAH_Content_ForecastContent_Block forecastContent)
        {
            forecastContent.MatchId = _matchId.ToString();
            switch (_betType)
            {
                case 1:
                    forecastContent.ToggleBetType = "3";
                    forecastContent.ToggleFC = Resources.Lang.lblViewOverUnderForecast;
                    break;
                case 3:
                    forecastContent.ToggleBetType = "1";
                    forecastContent.ToggleFC = Resources.Lang.lblViewHandicapForecast;
                    break;
                case 7:
                    forecastContent.ToggleBetType = "8";
                    forecastContent.ToggleFC = Resources.Lang.lblView1stOverUnderForecast;
                    break;
                case 8:
                    forecastContent.ToggleBetType = "7";
                    forecastContent.ToggleFC = Resources.Lang.lblView1stHandicapForecast;
                    break;
                default: break;
            }
        }
        /// <summary>
        /// Render forecast index link
        /// </summary>
        /// <param name="block"></param>
        private void RenderForecastIndexLink(FCAH_Content_ForecastContent_Block forecastContent)
        {
            // Render forecast point
            int indexCount = _betType == 1 || _betType == 7 ? 11 : 16;
            int endIndex = _betType == 1 || _betType == 7 ? _currentScore + 5 : 15;
            int selectedIndex = _currentScore;
            FCAH_Content_ForecastContent_ForecastPointContent_Block block = new FCAH_Content_ForecastContent_ForecastPointContent_Block();
            block.MatchId = _matchId.ToString();
            block.BetType = _betType.ToString();

            forecastContent.ForecastPointContent.Clear();
            for (int i = 0; i < indexCount; i++)
            {
                block.ForecastPoint = (endIndex).ToString();
                // Bold, red the selected forecast point
                block.ForecastPointValue = BoldSelectedScore(endIndex, selectedIndex);
                forecastContent.ForecastPointContent.Append(block);
                endIndex--;
            }
        }
        /// <summary>
        /// Render forecast index
        /// </summary>
        /// <param name="content"></param>
        private void RenderForecastIndex(FCAH_Content_ForecastContent_ForecastValue_Block forecastContent)
        {
            // Forecast score
            int startIndex = _betType == 1 || _betType == 7 ? _currentScore - 2 : _currentScore;
            forecastContent.VScore4 = (startIndex + 4).ToString();
            forecastContent.VScore3 = (startIndex + 3).ToString();
            forecastContent.VScore2 = (startIndex + 2).ToString();
            forecastContent.VScore1 = (startIndex + 1).ToString();
            forecastContent.VScore = (startIndex).ToString();
        }
        /// <summary>
        /// Only show bet list link if HasData=true
        /// </summary>
        /// <param name="viewData"></param>
        /// <param name="betListBlock"></param>
        private void RenderBetListLink(Hashtable viewData, FCAH_Content_ForecastContent_BetListLink_Block betListBlock)
        {
            if ((bool)viewData["HasData"])
            {
                betListBlock.MatchId = _matchId.ToString();
                betListBlock.BetType = _betType.ToString();
                betListBlock.BetTypeValue = Fanex.Age.UI.Common.BetListByBetTypeMatch;
            }
            else
            {
                betListBlock.Hide();
            }
        }
        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private string RedForPositiveAmount(object amount, byte decDigits)
        {
            if ((decimal)amount > 0)
                return "<font color='red'>" + Formater.DecFormat(Math.Round((decimal)amount), decDigits) + "</font>";
            else
                return Formater.DecFormat(Math.Round((decimal)amount), decDigits);

        }
        /// <summary>
        /// Bold the selected score
        /// </summary>
        /// <param name="index"></param>
        /// <param name="selectedIndex"></param>
        /// <returns></returns>
        private String BoldSelectedScore(int index, int selectedIndex)
        {
            const String boldSpan = "<span style='text-decoration:none;color:#FF0000;font-weight:bold;'>{0}</span>";
            return index == selectedIndex ? String.Format(boldSpan, index) : index.ToString();
        }

        private void RenderFPSArea(FCAH_Template tpl)
        {
            string fpsAPI = Sunplus.Agent.Model.BL.Definitions.AppSettings.FPSApi;
            if (string.IsNullOrEmpty(fpsAPI))
            {
                tpl.FPSArea.Hide();
                return;
            }

            int userId = CurrentUserSession.IsInternal
                ? CurrentUserSession.AdminId
                : CurrentUserSession.IsSubAcc ? CurrentUserSession.SubAccId : CurrentUserSession.UserId;
            tpl.FPSArea.userId = userId.ToString();
        }
        
        #endregion

        #endregion
    }
